if (msg.payload) {
    // Store all values from Wokwi ESP32 via MQTT
    if (msg.payload.td !== undefined) global.set("td", msg.payload.td);
    if (msg.payload.tp !== undefined) global.set("tp", msg.payload.tp);
    if (msg.payload.tq !== undefined) global.set("tq", msg.payload.tq);
    if (msg.payload.trs !== undefined) global.set("trs", msg.payload.trs);
    if (msg.payload.vitesse_rpm !== undefined) global.set("vitesse_rpm", msg.payload.vitesse_rpm);
    if (msg.payload.good_count !== undefined) global.set("good_count", msg.payload.good_count);
    if (msg.payload.reject_count !== undefined) global.set("reject_count", msg.payload.reject_count);
    if (msg.payload.total !== undefined) global.set("total", msg.payload.total);
    if (msg.payload.machine_state !== undefined) global.set("machine_state", msg.payload.machine_state);
    if (msg.payload.downtime_min !== undefined) global.set("runtime", msg.payload.downtime_min);
    if (msg.payload.machine_name !== undefined) global.set("machine_name", msg.payload.machine_name);
    if (msg.payload.nominal_rpm !== undefined) global.set("nominal_rpm", msg.payload.nominal_rpm);
    if (msg.payload.planned_time !== undefined) global.set("planned_time", msg.payload.planned_time);

    // Pass through for dashboard
    return msg;
}
return null;

let td = global.get("td") || 0;
let tp = global.get("tp") || 0;
let tq = global.get("tq") || 0;
let trs_from_esp = global.get("trs") || 0;
let machine_name = global.get("machine_name") || "MACHINE";
let good_count = global.get("good_count") || 0;
let reject_count = global.get("reject_count") || 0;
let total = global.get("total") || 0;
let vitesse_rpm = global.get("vitesse_rpm") || 0;
let runtime = global.get("runtime") || 0;

// Calculate TRS if not sent from ESP32
let TRS = trs_from_esp > 0 ? trs_from_esp : (td/100) * (tp/100) * (tq/100) * 100;

msg.payload = {
    trs: parseFloat(TRS.toFixed(1)),
    availability: parseFloat(td.toFixed(1)),
    performance: parseFloat(tp.toFixed(1)),
    quality: parseFloat(tq.toFixed(1)),
    total: total,
    good: good_count,
    reject: reject_count,
    machine: machine_name,
    vitesse_rpm: vitesse_rpm,
    runtime: runtime
};
return msg;

let trs = msg.payload.trs;
if (trs < 45) msg.payload = "🔴 Critique";
else if (trs < 65) msg.payload = "🟠 Faible";
else if (trs < 85) msg.payload = "🟡 Moyen";
else msg.payload = "🟢 World Class";
return msg;

let trs = msg.payload.trs;
if (trs < 45) msg.payload = "🔴 Pertes majeures - action urgente";
else if (trs < 65) msg.payload = "🟠 Performance insuffisante";
else if (trs < 85) msg.payload = "🟡 Acceptable avec amélioration possible";
else msg.payload = "🟢 Niveau d'excellence";
return msg;

let trs = msg.payload.trs;
let td = msg.payload.availability;
let tp = msg.payload.performance;
let tq = msg.payload.quality;
let lastState = context.get("lastTelegramState") || "ok";
let currentState;
if (trs >= 85) currentState = "ok";
else if (trs >= 65) currentState = "moyen";
else if (trs >= 45) currentState = "faible";
else currentState = "critique";
if (currentState === lastState) return null;
context.set("lastTelegramState", currentState);
let alertIcon, statusMsg;
if (currentState === "ok") { alertIcon = "🏆"; statusMsg = "WORLD CLASS — Performance optimale"; }
else if (currentState === "moyen") { alertIcon = "⚠️"; statusMsg = "MOYEN — Performance à surveiller"; }
else if (currentState === "faible") { alertIcon = "🟠"; statusMsg = "FAIBLE — Performance insuffisante"; }
else { alertIcon = "🔴"; statusMsg = "CRITIQUE — Action immédiate requise"; }
msg.payload = { chatId: 7789638269, type: "message", content: `${alertIcon} ${statusMsg}\n\n🏭 TRS: ${trs}%\n📊 TD: ${td}%\n⚡ TP: ${tp}%\n✅ TQ: ${tq}%\n\nPFA IMI4/2` };
return msg;

let trs = msg.payload.trs;
let lastState = context.get("lastAudioState") || "ok";
let currentState;
if (trs >= 85) currentState = "ok";
else if (trs >= 65) currentState = "moyen";
else if (trs >= 45) currentState = "faible";
else currentState = "critique";
if (currentState === lastState) return null;
context.set("lastAudioState", currentState);
if (currentState === "ok") msg.payload = "TRS revenu normal. Machine World Class.";
else if (currentState === "moyen") msg.payload = "Attention. TRS moyen. Surveillance requise.";
else if (currentState === "faible") msg.payload = "Alerte. TRS faible. Intervention nécessaire.";
else msg.payload = "Alerte critique. Arrêtez la machine immédiatement.";
return msg;

let trs = msg.payload.trs;
let td = msg.payload.availability;
let tp = msg.payload.performance;
let tq = msg.payload.quality;

let lastState = context.get("lastEmailState") || "ok";
let currentState;

if (trs >= 85) currentState = "ok";
else if (trs >= 65) currentState = "moyen";
else if (trs >= 45) currentState = "faible";
else currentState = "critique";

if (currentState === lastState) return null;
context.set("lastEmailState", currentState);

let emailContent = "";
let subject = "";

if (currentState === "ok") {
    subject = `🏆 WORLD CLASS - TRS: ${trs}%`;
    emailContent = `🏆 WORLD CLASS — Performance optimale

🏭 TRS: ${trs}%
📊 TD: ${td}%
⚡ TP: ${tp}%
✅ TQ: ${tq}%

PFA IMI4/2`;
}
else if (currentState === "moyen") {
    subject = `⚠️ MOYEN - TRS: ${trs}%`;
    emailContent = `⚠️ MOYEN — Performance à surveiller

🏭 TRS: ${trs}%
📊 TD: ${td}%
⚡ TP: ${tp}%
✅ TQ: ${tq}%

PFA IMI4/2`;
}
else if (currentState === "faible") {
    subject = `🟠 FAIBLE - TRS: ${trs}%`;
    emailContent = `🟠 ALERTE TRS — FAIBLE — Performance insuffisante, intervention nécessaire

🏭 TRS Global : ${trs}%
📊 Disponibilité (TD) : ${td}%
⚡ Performance (TP) : ${tp}%
✅ Qualité (TQ) : ${tq}%

PFA IMI4/2 — IoT TRS System`;
}
else {
    subject = `🔴 CRITIQUE - TRS: ${trs}%`;
    emailContent = `🔴 ALERTE TRS — CRITIQUE — Situation critique, action immédiate requise

🏭 TRS Global : ${trs}%
📊 Disponibilité (TD) : ${td}%
⚡ Performance (TP) : ${tp}%
✅ Qualité (TQ) : ${tq}%

PFA IMI4/2 — IoT TRS System`;
}

msg.topic = subject;
msg.payload = emailContent;

return msg;

if (msg.topic === 'params') {
    let params = {
        nominal_rpm: msg.payload.nominal_rpm,
        planned_time: msg.payload.planned_time,
        machine_name: msg.payload.machine_name
    };
    msg.payload = params;
    return msg;
}
return null;
